Here's a type-safe implementation:

```typescript
type LogLevel = "debug" | "info" | "warn" | "error";

type ConsoleMethod = (...args: unknown[]) => void;

const levelToMethod: Record<LogLevel, ConsoleMethod> = {
  debug: console.debug,
  info: console.info,
  warn: console.warn,
  error: console.error,
};

/**
 * Returns the console method matching the given log level.
 * The method is bound to `console` so it can be called standalone.
 */
function getConsoleMethod(level: LogLevel): ConsoleMethod {
  return levelToMethod[level].bind(console);
}

/**
 * Convenience helper: logs the arguments using the method for the given level.
 */
function log(level: LogLevel, ...args: unknown[]): void {
  getConsoleMethod(level)(...args);
}

export { type LogLevel, getConsoleMethod, log };
```

