## Extended version: events, durations, and exhaustiveness

```typescript
// Each state carries its own data (a discriminated union)
type LightState =
  | { kind: "red"; durationMs: number }
  | { kind: "green"; durationMs: number }
  | { kind: "yellow"; durationMs: number }
  | { kind: "flashingRed" }; // e.g. a malfunction/maintenance mode

type LightEvent =
  | { type: "TIMER" }
  | { type: "FAULT" }
  | { type: "RESET" };

const DURATIONS = {
  red: 30_000,
  green: 25_000,
  yellow: 5_000,
} as const;

// Helper that makes the compiler enforce exhaustive handling
function assertNever(x: never): never {
  throw new Error(`Unhandled case: ${JSON.stringify(x)}`);
}

function transition(state: LightState, event: LightEvent): LightState {
  switch (event.type) {
    case "FAULT":
      return { kind: "flashingRed" };

    case "RESET":
      return { kind: "red", durationMs: DURATIONS.red };

    case "TIMER":
      switch (state.kind) {
        case "red":
          return { kind: "green", durationMs: DURATIONS.green };
        case "green":
          return { kind: "yellow", durationMs: DURATIONS.yellow };
        case "yellow":
          return { kind: "red", durationMs: DURATIONS.red };
        case "flashingRed":
          return state; // timer has no effect while faulted
        default:
          return assertNever(state);
      }

    default:
      return assertNever(event);
  }
}

// Usage
let light: LightState = { kind: "red", durationMs: DURATIONS.red };
light = transition(light, { type: "TIMER" }); // green
light = transition(light, { type: "TIMER" }); // yellow
light = transition(light, { type: "FAULT" }); // flashingRed
light = transition(light, { type: "TIMER" }); // still flashingRed
light = transition(light, { type: "RESET" }); // red
```

