## Full state machine with data, events, and exhaustiveness checks

```typescript
// ---------- States (discriminated union) ----------
type RedState = {
  readonly kind: "red";
  readonly durationMs: number;
};

type GreenState = {
  readonly kind: "green";
  readonly durationMs: number;
};

type YellowState = {
  readonly kind: "yellow";
  readonly durationMs: number;
};

// Flashing red is used during a fault, like an all-way stop.
type FlashingRedState = {
  readonly kind: "flashingRed";
  readonly reason: string;
};

type LightState = RedState | GreenState | YellowState | FlashingRedState;

// ---------- Events ----------
type TimerExpired = { readonly type: "TIMER_EXPIRED" };
type PowerFault = { readonly type: "POWER_FAULT"; readonly reason: string };
type Reset = { readonly type: "RESET" };

type LightEvent = TimerExpired | PowerFault | Reset;

// ---------- Configuration ----------
const DURATIONS = {
  red: 30_000,
  green: 25_000,
  yellow: 5_000,
} as const satisfies Record<"red" | "green" | "yellow", number>;

// ---------- Helpers ----------
function assertNever(value: never): never {
  throw new Error(`Unhandled case: ${JSON.stringify(value)}`);
}

const red = (): RedState => ({ kind: "red", durationMs: DURATIONS.red });
const green = (): GreenState => ({ kind: "green", durationMs: DURATIONS.green });
const yellow = (): YellowState => ({ kind: "yellow", durationMs: DURATIONS.yellow });

// ---------- Transition function ----------
function transition(state: LightState, event: LightEvent): LightState {
  switch (event.type) {
    case "POWER_FAULT":
      return { kind: "flashingRed", reason: event.reason };

    case "RESET":
      return red();

    case "TIMER_EXPIRED":
      switch (state.kind) {
        case "red":
          return green();
        case "green":
          return yellow();
        case "yellow":
          return red();
        case "flashingRed":
          return state; // Stay flashing until RESET
        default:
          return assertNever(state);
      }

    default:
      return assertNever(event);
  }
}

// ---------- Usage ----------
let light: LightState = red();

light = transition(light, { type: "TIMER_EXPIRED" }); // green
light = transition(light, { type: "TIMER_EXPIRED" }); // yellow
light = transition(light, { type: "POWER_FAULT", reason: "Grid outage" }); // flashingRed
light = transition(light, { type: "TIMER_EXPIRED" }); // still flashingRed
light = transition(light, { type: "RESET" }); // red

console.log(light); // { kind: "red", durationMs: 30000 }
```

## Design notes

| Technique | Benefit |
|---|---|
| `Record<State, State>` | The compiler errors if you add a state but forget its transition |
| Generic `Next<S>` | The return type is exact (`"green"`), not just `TrafficLightState` |
| Discriminated unions (`kind` / `type`) | Each state can carry its own data, and TypeScript narrows the type in `switch` branches |
| `assertNever` | Compile-time error if a new state or event isn't handled |
| `readonly` + pure function | States are immutable, so transitions are easy to test and replay |
| `satisfies` | Validates the config shape while keeping the literal types |

Use the first version for simple cycling, the second when you want type-level guarantees about sequences, and the third for real-world logic with events, timing, and fault modes.

