### Extended version: states with data and events

If you need more realism (durations, a pedestrian button, a fault mode), a discriminated union with an event-driven reducer works well:

```typescript
type Light =
  | { kind: "red"; durationMs: 30_000 }
  | { kind: "green"; durationMs: 25_000 }
  | { kind: "yellow"; durationMs: 5_000 }
  | { kind: "flashingRed"; reason: string }; // fault / maintenance mode

type LightEvent =
  | { type: "TIMER_EXPIRED" }
  | { type: "FAULT"; reason: string }
  | { type: "RESET" };

const red: Light = { kind: "red", durationMs: 30_000 };
const green: Light = { kind: "green", durationMs: 25_000 };
const yellow: Light = { kind: "yellow", durationMs: 5_000 };

function transition(state: Light, event: LightEvent): Light {
  // A fault can occur from any state
  if (event.type === "FAULT") {
    return { kind: "flashingRed", reason: event.reason };
  }

  switch (state.kind) {
    case "red":
      return event.type === "TIMER_EXPIRED" ? green : state;
    case "green":
      return event.type === "TIMER_EXPIRED" ? yellow : state;
    case "yellow":
      return event.type === "TIMER_EXPIRED" ? red : state;
    case "flashingRed":
      return event.type === "RESET" ? red : state;
    default:
      return assertNever(state);
  }
}

// Compile-time exhaustiveness check: adding a new state without
// handling it in the switch causes a type error here.
function assertNever(x: never): never {
  throw new Error(`Unhandled state: ${JSON.stringify(x)}`);
}

// ----- Usage -----

let light: Light = red;
light = transition(light, { type: "TIMER_EXPIRED" });        // green
light = transition(light, { type: "TIMER_EXPIRED" });        // yellow
light = transition(light, { type: "FAULT", reason: "power" }); // flashingRed
light = transition(light, { type: "RESET" });                // red
```

### Key design points

- **`satisfies Record<...>`** guarantees the transition table is complete (no missing states) while preserving literal types, so `nextState("red")` is typed as exactly `"green"`, not just `TrafficLightState`.
- **Discriminated unions** (`kind` field) let TypeScript narrow the state in each `switch` branch.
- **`assertNever`** gives exhaustiveness checking, so adding a new state forces you to handle it.
- **Pure functions**: `transition` returns a new state rather than mutating, which makes it easy to test and to plug into React's `useReducer` or similar.

