  | { kind: "green"; durationMs: 25000 }
  | { kind: "yellow"; durationMs: 5000 };

type LightKind = Light["kind"];

type TrafficEvent =
  | { type: "TIMER_EXPIRED" }
  | { type: "EMERGENCY" }; // e.g. force red for emergency vehicles

