### Key design points

- **Union types** restrict states to valid values only.
- **Conditional types** (`NextState<S>`) let the compiler know the exact next state for a given literal input.
- **Mapped types** (`{ [S in TrafficLightState]: NextState<S> }`) ensure the runtime transition table matches the type-level rules. A wrong entry like `red: "yellow"` is a compile error.
- **Discriminated unions** (`kind` field) allow each state to carry its own data.
- **`assertNever`** guarantees exhaustive handling. Adding a new state or event without handling it causes a compile error.

Here's a design using a discriminated union, so each status carries only the data that makes sense for it, and the compiler checks that every status is handled.

```typescript
// ---------- Shared pieces ----------

type OrderId = string;
type Cents = number;

interface OrderItem {
  sku: string;
  name: string;
  quantity: number;
  unitPrice: Cents;
}

interface OrderBase {
  id: OrderId;
  customerId: string;
  items: OrderItem[];
  total: Cents;
  createdAt: Date;
}

// ---------- Status-specific variants ----------

interface PendingOrder extends OrderBase {
  status: "pending";
}

interface PaidOrder extends OrderBase {
  status: "paid";
  paidAt: Date;
  paymentId: string;
}

interface ShippedOrder extends OrderBase {
  status: "shipped";
  paidAt: Date;
  paymentId: string;
  shippedAt: Date;
  trackingNumber: string;
  carrier: string;
}

interface RefundedOrder extends OrderBase {
  status: "refunded";
  paidAt: Date;
  paymentId: string;
  refundedAt: Date;
  refundAmount: Cents;
  reason?: string;
}

// ---------- The union ----------

type Order = PendingOrder | PaidOrder | ShippedOrder | RefundedOrder;
type OrderStatus = Order["status"]; // "pending" | "paid" | "shipped" | "refunded"

// ---------- Helpers ----------

function assertNever(value: never): never {
  throw new Error(`Unhandled order status: ${JSON.stringify(value)}`);
}

// Label by status alone (useful for filters, dropdowns, badges)
const STATUS_LABELS: Record<OrderStatus, string> = {
  pending: "Pending Payment",
  paid: "Paid",
  shipped: "Shipped",
  refunded: "Refunded",
};

function getStatusLabel(status: OrderStatus): string {
  return STATUS_LABELS[status];
}

// Richer label that uses the variant-specific data
function getOrderDisplayLabel(order: Order): string {
  switch (order.status) {
    case "pending":
      return "Pending Payment";
    case "paid":
      return `Paid on ${order.paidAt.toLocaleDateString()}`;
    case "shipped":
      return `Shipped via ${order.carrier} (${order.trackingNumber})`;
    case "refunded":
      return `Refunded ${(order.refundAmount / 100).toFixed(2)} on ${order.refundedAt.toLocaleDateString()}`;
    default:
      return assertNever(order);
  }
}
```

**Usage**

```typescript
const order: Order = {
  id: "ord_123",
  customerId: "cus_456",
  items: [{ sku: "TS-01", name: "T-Shirt", quantity: 2, unitPrice: 2500 }],
  total: 5000,
  createdAt: new Date(),
  status: "shipped",
  paidAt: new Date(),
  paymentId: "pay_789",
  shippedAt: new Date(),
  trackingNumber: "1Z999AA10123456784",
  carrier: "UPS",
};

