  sku: string;
  name: string;
  quantity: number;
  unitPriceCents: number;
}

interface OrderBase {
  id: OrderId;
  customerId: string;
  items: OrderItem[];
  totalCents: number;
  createdAt: Date;
}

// ---------- Status-specific variants ----------

interface PendingOrder extends OrderBase {
  status: "pending";
}

interface PaidOrder extends OrderBase {
  status: "paid";
  paidAt: Date;
  paymentId: string;
}

interface ShippedOrder extends OrderBase {
  status: "shipped";
  paidAt: Date;
  paymentId: string;
  shippedAt: Date;
  trackingNumber: string;
  carrier: string;
}

interface RefundedOrder extends OrderBase {
  status: "refunded";
  paidAt: Date;
  paymentId: string;
  refundedAt: Date;
  refundAmountCents: number;
  reason?: string;
}

// ---------- The union ----------

type Order = PendingOrder | PaidOrder | ShippedOrder | RefundedOrder;

type OrderStatus = Order["status"]; // "pending" | "paid" | "shipped" | "refunded"

// ---------- Simple label per status ----------

const STATUS_LABELS: Record<OrderStatus, string> = {
  pending: "Pending Payment",
  paid: "Paid",
  shipped: "Shipped",
  refunded: "Refunded",
};

function getStatusLabel(status: OrderStatus): string {
  return STATUS_LABELS[status];
}

// ---------- Detailed label using status-specific data ----------

function getOrderDisplayLabel(order: Order): string {
  switch (order.status) {
    case "pending":
      return "Pending Payment";
    case "paid":
      return `Paid on ${order.paidAt.toLocaleDateString()}`;
    case "shipped":
      return `Shipped via ${order.carrier} (${order.trackingNumber})`;
    case "refunded":
      return `Refunded $${(order.refundAmountCents / 100).toFixed(2)}`;
    default: {
      // Compile-time exhaustiveness check: errors if a new status is added
      // to the union but not handled above.
      const _exhaustive: never = order;
      return _exhaustive;
    }
  }
}
```

**Example usage**

```typescript
const order: Order = {
  id: "ord_123",
  customerId: "cus_42",
  items: [{ sku: "A1", name: "Widget", quantity: 2, unitPriceCents: 1500 }],
  totalCents: 3000,
  createdAt: new Date(),
  status: "shipped",
  paidAt: new Date(),
  paymentId: "pay_789",
  shippedAt: new Date(),
  trackingNumber: "1Z999",
  carrier: "UPS",
};

console.log(getStatusLabel(order.status));   // "Shipped"
console.log(getOrderDisplayLabel(order));    // "Shipped via UPS (1Z999)"
```

**Why this design**

- **Discriminated union:** Checking `order.status` narrows the type automatically, so `order.trackingNumber` is only accessible when the order is `"shipped"`.
- **Impossible states are unrepresentable:** A pending order can't have a tracking number, and a shipped order must have one.
- **Exhaustiveness checking:** The `never` assignment in `getOrderDisplayLabel` and the `Record<OrderStatus, string>` in `STATUS_LABELS` both cause compile errors if you add a new status and forget to update them.

If you only need the simple label, `getStatusLabel` is enough. If you want richer text that uses each variant's fields, use `getOrderDisplayLabel`.

