  status: "paid";
  paidAt: ISODateString;
  paymentId: string;
}

interface ShippedOrder extends OrderBase {
  status: "shipped";
  paidAt: ISODateString;
  paymentId: string;
  shippedAt: ISODateString;
  trackingNumber: string;
  carrier: string;
}

interface RefundedOrder extends OrderBase {
  status: "refunded";
  paymentId: string;
  refundedAt: ISODateString;
  refundAmountCents: number;
  reason?: string;
}

// ---------- The union ----------

export type Order = PendingOrder | PaidOrder | ShippedOrder | RefundedOrder;

export type OrderStatus = Order["status"]; // "pending" | "paid" | "shipped" | "refunded"

// ---------- Display labels ----------

const STATUS_LABELS: Record<OrderStatus, string> = {
  pending: "Pending Payment",
  paid: "Paid",
  shipped: "Shipped",
  refunded: "Refunded",
};

/** Simple label from a status alone. */
export function getStatusLabel(status: OrderStatus): string {
  return STATUS_LABELS[status];
}

/** Detailed label that uses status-specific data. */
export function getOrderDisplayLabel(order: Order): string {
  switch (order.status) {
    case "pending":
      return "Pending Payment";
    case "paid":
      return `Paid on ${new Date(order.paidAt).toLocaleDateString()}`;
    case "shipped":
      return `Shipped via ${order.carrier} (${order.trackingNumber})`;
    case "refunded":
      return `Refunded ${(order.refundAmountCents / 100).toFixed(2)} ${order.currency}`;
    default: {
      // Compile-time exhaustiveness check: adding a new status
      // without handling it above will cause a type error here.
      const _exhaustive: never = order;
      return _exhaustive;
    }
  }
}
```

**Usage**

```typescript
const order: Order = {
  id: "ord_123",
  customerId: "cus_9",
  items: [{ sku: "A1", name: "Widget", quantity: 2, unitPriceCents: 1500 }],
  totalCents: 3000,
  currency: "USD",
