## Caveats

**1. Method binding.** In some environments, extracted console methods lose their `this` context. Modern browsers and Node handle this fine, but if you need to be safe (or want to pick up later `console` patching, e.g. by test spies), use a lookup that resolves at call time:

```typescript
function getConsoleMethod(level: LogLevel): ConsoleMethod {
  return (...args) => console[level](...args);
}
```

**2. Handling untrusted input.** If the level comes from config or an environment variable, add a type guard and a fallback:

```typescript
const LOG_LEVELS = ["debug", "info", "warn", "error"] as const;
type LogLevel = (typeof LOG_LEVELS)[number];

function isLogLevel(value: string): value is LogLevel {
  return (LOG_LEVELS as readonly string[]).includes(value);
}

function getConsoleMethod(level: string, fallback: LogLevel = "info"): ConsoleMethod {
  const safe = isLogLevel(level) ? level : fallback;
  return (...args) => console[safe](...args);
}

// Usage
const log = getConsoleMethod(process.env.LOG_LEVEL ?? "info");
log("Server started");
```

