 * Returns the next state in the cycle: red -> green -> yellow -> red.
 * The generic signature gives literal-precise return types.
 */
export function nextState<S extends TrafficLightState>(current: S): NextState<S> {
  return transitions[current];
}

// ---------- Usage ----------

