 * For each state, maps each event type to the next state.
 * Using a mapped type ensures every state and every event is handled,
 * so adding a new one causes a compile error until it's covered.
 */
type TransitionTable = {
  [S in LightState]: {
    [E in LightEvent["type"]]: LightState;
  };
};

const transitions: TransitionTable = {
  green: {
    TIMER_ELAPSED: "yellow",
    EMERGENCY: "red",
    RESET: INITIAL_STATE,
  },
  yellow: {
    TIMER_ELAPSED: "red",
    EMERGENCY: "red",
    RESET: INITIAL_STATE,
  },
  red: {
    TIMER_ELAPSED: "green",
    EMERGENCY: "red",
    RESET: INITIAL_STATE,
  },
};

// ---------- Transition function ----------

/**
 * Returns the next state given the current state and an event.
 * Defaults to the timer event for the simple "advance" case.
 */
export function nextState(
  current: LightState,
  event: LightEvent = { type: "TIMER_ELAPSED" }
): LightState {
  return transitions[current][event.type];
}

// ---------- Usage ----------

