```ts
export type OrderStatus = 'pending' | 'paid' | 'shipped' | 'refunded';

export interface Order {
  id: string;
  amount: number;
  status: OrderStatus;
  createdAt: Date;
}

const ORDER_STATUS_LABELS: Record<OrderStatus, string> = {
  pending: 'Pending',
  paid: 'Paid',
  shipped: 'Shipped',
  refunded: 'Refunded',
};

export function getOrderStatusLabel(status: OrderStatus): string {
  return ORDER_STATUS_LABELS[status];
}
```

### Example usage

```ts
const order: Order = {
  id: 'ord_123',
  amount: 4999,
  status: 'shipped',
  createdAt: new Date(),
};

console.log(getOrderStatusLabel(order.status)); // "Shipped"
```

Using `Record<OrderStatus, string>` ensures compile-time exhaustiveness—if you add a new status to `OrderStatus`, TypeScript will require you to add its label to `ORDER_STATUS_LABELS`.

