type OrderStatus =
  | { status: "pending" }
  | { status: "paid"; paidAt: Date; paymentId: string }
  | { status: "shipped"; shippedAt: Date; trackingNumber: string }
  | { status: "refunded"; refundedAt: Date; refundAmount: number };

// Order type using the status union
interface Order {
  id: string;
  customerName: string;
  total: number;
  createdAt: Date;
  status: OrderStatus;
}

// Function returning a display label for each status
function getStatusLabel(order: Order): string {
  switch (order.status.status) {
    case "pending":
      return "Pending payment";
    case "paid":
      return `Paid on ${order.status.paidAt.toLocaleDateString()}`;
    case "shipped":
      return `Shipped — tracking #${order.status.trackingNumber}`;
    case "refunded":
      return `Refunded $${order.status.refundAmount.toFixed(2)}`;
  }
}
```

## Example usage

```typescript
const order: Order = {
  id: "ord-123",
  customerName: "Alice",
  total: 49.99,
  createdAt: new Date(),
  status: { status: "shipped", shippedAt: new Date(), trackingNumber: "1Z999AA1" },
};

getStatusLabel(order); // "Shipped — tracking #1Z999AA1"
```

## Why this approach?

- **Exhaustive checking**: TypeScript ensures the `switch` handles every status. If you add a new status (e.g., `"cancelled"`), the compiler errors until you handle it.
- **Type narrowing**: Inside each `case`, `order.status` narrows to that specific variant, so fields like `trackingNumber` are safely accessible.
- **Status-specific data**: Each variant carries only the fields relevant to it — a pending order can't have a tracking number, and the types enforce that.

