export type TrafficLightTransition = {
  from: TrafficLightState;
  to: TrafficLightState;
};

export const transitions: Record<TrafficLightState, TrafficLightTransition> = {
  red: { from: 'red', to: 'green' },
  green: { from: 'green', to: 'yellow' },
  yellow: { from: 'yellow', to: 'red' },
};

export function getNextState(current: TrafficLightState): TrafficLightState {
  return transitions[current].to;
}
```

Usage:

```ts
getNextState('red');    // 'green'
getNextState('green');  // 'yellow'
getNextState('yellow'); // 'red'
```

This models the cycle: `red → green → yellow → red`.

```ts
