```typescript
type LogLevel = "debug" | "info" | "warn" | "error";

function log(level: LogLevel, ...args: unknown[]): void {
  const method: Record<LogLevel, (...args: unknown[]) => void> = {
    debug: console.debug,
    info: console.info,
    warn: console.warn,
    error: console.error,
  };

  method[level](...args);
}

// Usage
