  debug: console.debug,
  info: console.info,
  warn: console.warn,
  error: console.error,
};

function log(level: LogLevel, ...args: unknown[]): void {
  consoleMethods[level](...args);
}

// Usage:
log("info", "Server started on port", 3000);
log("error", "Something went wrong", new Error("boom"));
```

