## Types

```ts
// ---------- Core types ----------

export type LightColor = 'red' | 'amber' | 'green';

/**
 * Discriminated union: `color` is the discriminant, so narrowing on it
 * gives you the matching `phase` for free.
 */
export type TrafficLightState =
  | { readonly color: 'red';   readonly phase: 'stop' }
  | { readonly color: 'amber'; readonly phase: 'caution' }
  | { readonly color: 'green'; readonly phase: 'go' };

/** Canonical state objects (frozen, safe to share). */
export const STATES = {
  red:   { color: 'red',   phase: 'stop' }    as const,
  amber: { color: 'amber', phase: 'caution' } as const,
  green: { color: 'green', phase: 'go' }      as const,
} satisfies { readonly [C in LightColor]: TrafficLightState };

/** Transition table — `satisfies` keeps the literal types while checking completeness. */
export const TRANSITIONS = {
  red:   'amber',
  amber: 'green',
  green: 'red',
} satisfies { readonly [C in LightColor]: LightColor };

/** Compile-time exhaustiveness helper. */
export function assertNever(value: never): never {
  throw new Error(`Unhandled state: ${JSON.stringify(value)}`);
}
```

## The `nextState` function

```ts
export function nextState(state: TrafficLightState): TrafficLightState {
  const next = TRANSITIONS[state.color];
  return STATES[next];
}

/** Convenience overload for callers that only track the color. */
export function nextColor(color: LightColor): LightColor {
  return TRANSITIONS[color];
}
```

Because `TRANSITIONS` is typed as `{ [C in LightColor]: LightColor }`, adding a fourth color to `LightColor` is a **compile error** until you add its transition — the map can't silently fall back to `undefined`.

## A stateful machine

```ts
export interface TrafficLightOptions {
  readonly initial?: TrafficLightState;
  /** Milliseconds each color stays lit. */
  readonly durations?: Partial<Record<LightColor, number>>;
}

const DEFAULT_DURATIONS: Record<LightColor, number> = {
  red: 10_000,
  amber: 3_000,
  green: 15_000,
};

export class TrafficLight {
  #state: TrafficLightState;
  #elapsedMs = 0;
  readonly #durations: Record<LightColor, number>;

  constructor(options: TrafficLightOptions = {}) {
    this.#state = options.initial ?? STATES.red;
    this.#durations = { ...DEFAULT_DURATIONS, ...options.durations };

    for (const [color, ms] of Object.entries(this.#durations)) {
      if (!Number.isFinite(ms) || ms <= 0) {
        throw new RangeError(`Duration for "${color}" must be a positive number`);
      }
    }
  }

  get state(): TrafficLightState {
    return this.#state;
  }

  get color(): LightColor {
    return this.#state.color;
  }

  /** Time left in the current phase. */
  get remainingMs(): number {
    return Math.max(0, this.#durations[this.#state.color] - this.#elapsedMs);
  }

  /** Advance the clock; returns the state after the elapsed time. */
  tick(deltaMs: number): TrafficLightState {
    if (!Number.isFinite(deltaMs) || deltaMs < 0) {
      throw new RangeError('deltaMs must be a non-negative finite number');
    }

    this.#elapsedMs += deltaMs;

    // A single tick may span several phases (e.g. a long GC pause).
    while (this.#elapsedMs >= this.#durations[this.#state.color]) {
      this.#elapsedMs -= this.#durations[this.#state.color];
      this.#state = nextState(this.#state);
    }

    return this.#state;
  }

  /** Type guard for "cars may proceed". */
  get isGo(): boolean {
    return this.#state.color === 'green';
  }
}
```

## Usage

```ts
const light = new TrafficLight({ durations: { green: 20_000 } });

light.tick(10_000);          // -> amber
light.state.phase;           // 'caution'  (narrowed, no cast needed)

light.tick(3_000);           // -> green
light.isGo;                  // true

light.tick(20_000);          // -> red
```

### Notes on the design

- **Discriminated union over a plain string union** — `state.phase` is only accessible after narrowing on `state.color`, so you can't read a phase that doesn't belong to the current color.
- **`satisfies` instead of `as`** — the transition table keeps its literal types (`'red' | 'amber' | 'green'`) while still being checked against the mapped type.
- **Loop instead of `if` in `tick`** — handles elapsed time that crosses multiple phase boundaries in one call.
- **Runtime validation of durations** — a `0` duration would make the `while` loop spin forever, so it's rejected in the constructor.

# Traffic Light State Machine in TypeScript

## 1. Core types

```ts
// The set of valid states, derived from a runtime array so the union and the
// runtime values can never drift apart.
export const TRAFFIC_LIGHT_STATES = ["red", "yellow", "green"] as const;

export type TrafficLightState = (typeof TRAFFIC_LIGHT_STATES)[number];
```

## 2. Transition table + `nextState`

Using `satisfies` (TS 4.9+) gives you both literal types *and* a compile-time check that every state has a transition.

```ts
export const NEXT_STATE = {
  red: "green",
  green: "yellow",
  yellow: "red",
} as const satisfies Record<TrafficLightState, TrafficLightState>;

export function nextState(current: TrafficLightState): TrafficLightState {
  return NEXT_STATE[current];
}
```

### Alternative: `switch` with exhaustiveness checking

If you prefer a `switch`, the `never` guard makes the compiler error if you ever add a state and forget to handle it.

```ts
function assertNever(value: never): never {
  throw new Error(`Unhandled traffic light state: ${String(value)}`);
}

export function nextState(current: TrafficLightState): TrafficLightState {
  switch (current) {
    case "red":
      return "green";
    case "green":
      return "yellow";
    case "yellow":
      return "red";
    default:
      return assertNever(current); // <- current is `never` here
  }
}
```

## 3. Runtime validation (parsing untrusted input)

```ts
export function isTrafficLightState(value: unknown): value is TrafficLightState {
  return (
    typeof value === "string" &&
    (TRAFFIC_LIGHT_STATES as readonly string[]).includes(value)
  );
}

export function parseState(value: unknown): TrafficLightState {
  if (!isTrafficLightState(value)) {
    throw new Error(`Invalid traffic light state: ${String(value)}`);
  }
  return value;
}
```

## 4. Event-driven variant

A real signal reacts to *events*, not just a timer. Model events as a discriminated union so payloads are type-safe per event.

```ts
export type TrafficEvent =
  | { type: "TIMER_ELAPSED" }
  | { type: "PEDESTRIAN_BUTTON" }
  | { type: "EMERGENCY_OVERRIDE" };

export type TrafficEventType = TrafficEvent["type"];

export const TRANSITIONS = {
  red: {
    TIMER_ELAPSED: "green",
    PEDESTRIAN_BUTTON: "red",
    EMERGENCY_OVERRIDE: "red",
  },
  green: {
    TIMER_ELAPSED: "yellow",
    PEDESTRIAN_BUTTON: "yellow",
    EMERGENCY_OVERRIDE: "red",
  },
  yellow: {
    TIMER_ELAPSED: "red",
    PEDESTRIAN_BUTTON: "red",
    EMERGENCY_OVERRIDE: "red",
  },
} as const satisfies Record<
  TrafficLightState,
  Record<TrafficEventType, TrafficLightState>
>;

export function transition(
  state: TrafficLightState,
  event: TrafficEvent,
): TrafficLightState {
  return TRANSITIONS[state][event.type];
}
```

## 5. Stateful machine

```ts
export class TrafficLight {
  #state: TrafficLightState = "red";

  get state(): TrafficLightState {
    return this.#state;
  }

  /** Advance one step in the cycle. */
  advance(): TrafficLightState {
    this.#state = nextState(this.#state);
    return this.#state;
  }

  /** Apply an event. */
  send(event: TrafficEvent): TrafficLightState {
    this.#state = transition(this.#state, event);
    return this.#state;
  }
}
```

## 6. Richer model: states carrying data

When a state needs payload (e.g. a countdown), use a discriminated union instead of a string union:

```ts
export type LightState =
  | { readonly kind: "red"; readonly pedestrianWaiting: boolean }
  | { readonly kind: "yellow"; readonly secondsLeft: number }
  | { readonly kind: "green"; readonly secondsLeft: number };

export function tick(state: LightState): LightState {
  switch (state.kind) {
    case "red":
      return { kind: "green", secondsLeft: 30 };
    case "green":
      return { kind: "yellow", secondsLeft: 3 };
    case "yellow":
      return { kind: "red", pedestrianWaiting: false };
    default:
      return assertNever(state);
  }
}
```

## Notes

- **`as const satisfies X`** is the key idiom: `as const` preserves literal types, `satisfies` enforces the shape without widening it.
- **`assertNever`** turns "I forgot a case" into a compile error rather than a silent `undefined` at runtime.
- **Discriminated unions** (`{ kind: ... }`, `{ type: ... }`) let TypeScript narrow correctly in `switch` statements — prefer them over optional properties.
- If you want the compiler to enforce *reachability* (e.g. "red can never follow green"), model the transition table as the single source of truth and derive `nextState` from it, as in §2.

## Core types and transition function

```ts
// The set of valid states, derived from a const array so the union stays in sync.
export const TRAFFIC_LIGHT_STATES = ["red", "yellow", "green"] as const;

export type TrafficLightState = (typeof TRAFFIC_LIGHT_STATES)[number];

// A transition table: every state maps to exactly one next state.
// The mapped type guarantees exhaustiveness — adding a state to the union
// without adding an entry here is a compile-time error.
export const TRANSITIONS: {
  readonly [S in TrafficLightState]: TrafficLightState;
} = {
  red: "green",
  yellow: "red",
  green: "yellow",
};

export function nextState(current: TrafficLightState): TrafficLightState {
  return TRANSITIONS[current];
}
