  #state: TrafficLightState = "red";

  get state(): TrafficLightState {
    return this.#state;
  }

  /** Advance to the next state and return it. */
  tick(): TrafficLightState {
    this.#state = nextState(this.#state);
    return this.#state;
  }

  /** Jump to a specific state (e.g. for a pedestrian button). */
  setState(state: TrafficLightState): void {
    this.#state = state;
  }
}
```

## Example usage

```ts
const light = new TrafficLight();

console.log(light.tick()); // "green"
console.log(light.tick()); // "yellow"
console.log(light.tick()); // "red"

light.setState("green");
console.log(nextState(light.state)); // "yellow"
```

## Notes

- `TrafficLightState` is a closed union, so invalid strings like `"blue"` are rejected at compile time.
- The mapped type on `TRANSITIONS` makes the table exhaustive: if you add `"blue"` to `TRAFFIC_LIGHT_STATES`, TypeScript will error until you add a `blue` entry.
- If you want a different cycle order (e.g. red → green → yellow → red), just change the table values — the types stay valid.

