 * Throws at runtime if `current` is not a valid state (the type system
 * prevents this for statically-typed callers).
 */
export function nextState(
  current: TrafficLightState,
  transitions: TrafficLightTransitions = DEFAULT_TRANSITIONS,
): TrafficLightState {
  if (!isTrafficLightState(current)) {
    throw new Error(`Invalid traffic light state: ${String(current)}`);
  }
  return transitions[current];
}
```

