# Traffic Light State Machine in TypeScript

## 1. Core: states, transition table, and `nextState`

```ts
// ---------------------------------------------------------------------------
// States
// ---------------------------------------------------------------------------

/**
 * The canonical list of states. Deriving the union from the tuple means the
 * runtime array and the compile-time type can never drift apart.
 */
export const TRAFFIC_LIGHT_STATES = ["red", "yellow", "green"] as const;

export type TrafficLightState = (typeof TRAFFIC_LIGHT_STATES)[number];

// ---------------------------------------------------------------------------
// Transitions
// ---------------------------------------------------------------------------

/**
 * The transition table. `satisfies` checks the shape *without* widening the
 * literal types, so `NEXT_STATE.red` is still typed as `"green"`.
 *
 * The mapped type `{ [S in TrafficLightState]: TrafficLightState }` makes the
 * table exhaustive: adding a new state to `TRAFFIC_LIGHT_STATES` immediately
 * produces a compile error here until you add its transition.
 */
export const NEXT_STATE = {
  red: "green",
  green: "yellow",
  yellow: "red",
} as const satisfies { readonly [S in TrafficLightState]: TrafficLightState };

// ---------------------------------------------------------------------------
// The function you asked for
// ---------------------------------------------------------------------------

/**
 * Returns the next state for a given current state.
 *
 * @param current - The current state of the light.
 * @returns The next state in the cycle.
 */
export function nextState(current: TrafficLightState): TrafficLightState {
  return NEXT_STATE[current];
}
```

Usage:

```ts
