## 2. Exhaustive-check pattern (catches missing cases at compile time)

If you prefer a `switch` over a lookup table, use a `never` guard so that adding
a new state becomes a type error rather than a silent runtime bug:

```ts
export function assertNever(value: never, context = "Unexpected value"): never {
  throw new Error(`${context}: ${String(value)}`);
}

export function nextStateBySwitch(current: TrafficLightState): TrafficLightState {
  switch (current) {
    case "red":
      return "green";
    case "green":
      return "yellow";
    case "yellow":
      return "red";
    default:
      // If a 4th state is added, `current` is no longer `never` here → error.
      return assertNever(current, "Unknown traffic light state");
  }
}
```

