## 3. Extended: event-driven machine with a discriminated union

A more realistic model where states carry data and transitions depend on
*events*, not just the current state:

```ts
// ---------------------------------------------------------------------------
// Events
// ---------------------------------------------------------------------------

export type TrafficLightEvent =
  | { readonly type: "timer" }
  | { readonly type: "pedestrian-button" };

export type TrafficLightEventType = TrafficLightEvent["type"];

// ---------------------------------------------------------------------------
// States (discriminated union — each variant carries its own payload)
// ---------------------------------------------------------------------------

export type MachineState =
  | { readonly phase: "red"; readonly pedestrian: "stop" | "walk" }
  | { readonly phase: "green"; readonly pedestrian: "stop" }
  | { readonly phase: "yellow"; readonly pedestrian: "stop" }
  | { readonly phase: "crossing"; readonly pedestrian: "walk" };

export type MachinePhase = MachineState["phase"];

// ---------------------------------------------------------------------------
// Transition table: state -> event -> next state
// ---------------------------------------------------------------------------

export const TRANSITIONS = {
  red: {
    timer: { phase: "green", pedestrian: "stop" },
    "pedestrian-button": { phase: "crossing", pedestrian: "walk" },
  },
  green: {
    timer: { phase: "yellow", pedestrian: "stop" },
  },
  yellow: {
    timer: { phase: "red", pedestrian: "stop" },
  },
  crossing: {
    timer: { phase: "red", pedestrian: "stop" },
  },
} as const satisfies {
  readonly [P in MachinePhase]: Partial<
    Record<TrafficLightEventType, MachineState>
  >;
};

// ---------------------------------------------------------------------------
// Reducer
// ---------------------------------------------------------------------------

/**
 * Applies an event to a state.
 *
 * @returns The next state, or `undefined` if the event is not valid for the
 *          current state (e.g. pressing the pedestrian button while green).
 */
export function transition(
  state: MachineState,
  event: TrafficLightEvent,
): MachineState | undefined {
  const table = TRANSITIONS[state.phase] as
    | Partial<Record<TrafficLightEventType, MachineState>>
    | undefined;

  return table?.[event.type];
}

/**
 * A pure reducer over a sequence of events.
 */
export function reduce(
  states: readonly MachineState[],
  events: readonly TrafficLightEvent[],
): MachineState[] {
  const result: MachineState[] = [];

  for (const event of events) {
    const current = result[result.length - 1] ?? states[0];
    const next = transition(current, event);
    if (next) result.push(next);
  }

  return result;
}
```

