## 4. Runtime validation for untrusted input

Types vanish at runtime, so validate anything coming from the network, DOM,
`localStorage`, etc.:

```ts
export function isTrafficLightState(value: unknown): value is TrafficLightState {
  return (
    typeof value === "string" &&
    (TRAFFIC_LIGHT_STATES as readonly string[]).includes(value)
  );
}

export function parseTrafficLightState(value: unknown): TrafficLightState {
  if (!isTrafficLightState(value)) {
    throw new TypeError(`Invalid traffic light state: ${JSON.stringify(value)}`);
  }
  return value;
}
```

