## 3. Exhaustive `switch` variant

Useful when transitions depend on more than a lookup. The `never` check makes the compiler error if you add a state and forget to handle it.

```ts
export function assertNever(value: never): never {
  throw new Error(`Unhandled value: ${String(value)}`);
}

export function nextStateBySwitch(current: TrafficLightState): TrafficLightState {
  switch (current) {
    case "red":
      return "green";
    case "yellow":
      return "red";
    case "green":
      return "yellow";
    default:
      return assertNever(current); // <- compile error on a missing case
  }
}
```

## 4. Event-driven version (discriminated union)

```ts
export type TrafficLightEvent =
  | { readonly type: "timerExpired" }
  | { readonly type: "pedestrianRequested" };

export function reduce(
  state: TrafficLightState,
  event: TrafficLightEvent,
): TrafficLightState {
  switch (event.type) {
    case "timerExpired":
      return nextState(state);
    case "pedestrianRequested":
      // Only interrupt green; red/yellow stay put.
      return state === "green" ? "yellow" : state;
    default:
      return assertNever(event);
  }
