## 6. Generic reusable machine

```ts
export type StateMachine<
  S extends string,
  E extends { readonly type: string },
> = {
  readonly initial: S;
  readonly transitions: {
    readonly [K in S]: (event: E, state: S) => S;
  };
};

export const trafficLight: StateMachine<TrafficLightState, TrafficLightEvent> = {
  initial: "red",
  transitions: {
    red: (event) => (event.type === "timerExpired" ? "green" : "red"),
    yellow: (event) => (event.type === "timerExpired" ? "red" : "yellow"),
    green: (event) => (event.type === "pedestrianRequested" ? "yellow" : "green"),
  },
};

export function send(
  machine: StateMachine<TrafficLightState, TrafficLightEvent>,
  state: TrafficLightState,
  event: TrafficLightEvent,
): TrafficLightState {
  return machine.transitions[state](event, state);
}
```

### Notes

- **`as const satisfies X`** is the key idiom: `as const` preserves literal types for autocomplete, `satisfies` validates the shape. Use `satisfies` alone if you want the values widened to `TrafficLightState`.
- **`assertNever`** gives you compile-time exhaustiveness; the `throw` is just a runtime fallback for JS callers.
- **Discriminated unions** (`{ type: "..." }`) let TypeScript narrow both the state and the event in a `switch`, so `default` branches are provably unreachable.
- If you enable `noUncheckedIndexedAccess`, index access like `TRANSITIONS[current]` returns `TrafficLightState | undefined` — the mapped type `TransitionTable<S>` avoids that because every key is known to exist.

## Core types

```ts
// ---------- Types ----------

export const LIGHT_COLORS = ['red', 'amber', 'green'] as const;
export type LightColor = (typeof LIGHT_COLORS)[number];

/**
 * Discriminated union on `color`, so `switch` narrows correctly.
 * `phase` is a second literal that documents *why* the light is in that color.
 */
export type TrafficLightState =
  | { readonly color: 'red'; readonly phase: 'stop' }
  | { readonly color: 'amber'; readonly phase: 'prepare' }
  | { readonly color: 'green'; readonly phase: 'go' };

export type TrafficLightEvent =
  | { readonly type: 'TICK' }              // the timer elapsed
  | { readonly type: 'REQUEST_CROSSING' }; // pedestrian button pressed

/** Maps an event type to the state it may lead to. */
export type EventMap = {
  TICK: TrafficLightState;
  REQUEST_CROSSING: TrafficLightState;
};

/**
 * Transition table: for each source color, which target state each event leads to.
 * Events are optional per-state, so an unhandled event is a type error at the
 * table, not a runtime surprise.
 */
export type TransitionTable = {
  readonly [S in TrafficLightState['color']]: {
    readonly [E in keyof EventMap]?: EventMap[E];
  };
};
```

## The machine

```ts
// ---------- Machine ----------

export const INITIAL_STATE: TrafficLightState = { color: 'red', phase: 'stop' };

export const TRANSITIONS = {
  red: {
    TICK: { color: 'amber', phase: 'prepare' },
    REQUEST_CROSSING: { color: 'red', phase: 'stop' },
  },
  amber: {
    TICK: { color: 'green', phase: 'go' },
    REQUEST_CROSSING: { color: 'red', phase: 'stop' },
  },
  green: {
    TICK: { color: 'red', phase: 'stop' },
    REQUEST_CROSSING: { color: 'red', phase: 'stop' },
  },
} as const satisfies TransitionTable;

/** The next state in the normal red → amber → green → red cycle. */
export function nextState(state: TrafficLightState): TrafficLightState {
  return TRANSITIONS[state.color].TICK;
}

/** Just the color of the next state, if you don't care about the phase. */
export function nextColor(state: TrafficLightState): LightColor {
  return nextState(state).color;
}

/** Event-driven transition. Returns the same state if the event is not handled. */
export function send(
  state: TrafficLightState,
  event: TrafficLightEvent,
): TrafficLightState {
  const table = TRANSITIONS[state.color] as Partial<
    Record<TrafficLightEvent['type'], TrafficLightState>
  >;
  return table[event.type] ?? state;
}

/** Compile-time exhaustiveness check for `switch` statements. */
export function assertNever(value: never): never {
  throw new Error(`Unhandled state: ${JSON.stringify(value)}`);
}
```

## Usage

```ts
let state: TrafficLightState = INITIAL_STATE;

state = nextState(state); // { color: 'amber', phase: 'prepare' }
state = nextState(state); // { color: 'green', phase: 'go' }
state = nextState(state); // { color: 'red', phase: 'stop' }

state = send(state, { type: 'REQUEST_CROSSING' }); // stays red

// Narrowing works because of the discriminated union:
switch (state.color) {
  case 'red':
    console.log('Stop.'); break;
  case 'amber':
    console.log('Prepare to go.'); break;
  case 'green':
    console.log('Go.'); break;
  default:
    assertNever(state); // errors if a new color is added without handling it
}
```

## Optional: a stateful wrapper with durations

```ts
export type TimedState = TrafficLightState & { readonly elapsedMs: number };

export const DURATIONS: Record<LightColor, number> = {
  red: 10_000,
  amber: 3_000,
  green: 15_000,
};

export function tick(state: TimedState, deltaMs: number): TimedState {
  const elapsedMs = state.elapsedMs + deltaMs;
  if (elapsedMs < DURATIONS[state.color]) {
    return { ...state, elapsedMs };
  }
  return { ...nextState(state), elapsedMs: 0 };
}
```

**Design notes**

- `as const satisfies TransitionTable` keeps the literal types (so `nextState` returns a precise union) *and* checks the table against the declared shape — `satisfies` gives you both, unlike a plain annotation.
- The union is discriminated on `color`, so `state.phase` is narrowed to `'stop' | 'prepare' | 'go'` inside each `case`.
- Transitions are data, not `switch` statements, so adding a color or an event is a compile-time-checked change in one place.
- States are `readonly`, so a transition can't mutate the current state in place — `nextState` always returns a fresh value.

