## Full machine with events and error handling

```ts
export type TrafficLightState = "red" | "yellow" | "green";

export type TrafficLightEvent =
  | { type: "timer" }        // automatic progression
  | { type: "button" };      // manual request

export interface TrafficLightConfig {
  /** Order of automatic progression. Defaults to red → green → yellow → red. */
  cycle?: readonly TrafficLightState[];
  /** Whether a button press may skip ahead. */
  allowButton?: boolean;
}

export class InvalidTransitionError extends Error {
  constructor(
    public readonly state: TrafficLightState,
    public readonly event: TrafficLightEvent,
  ) {
    super(`Cannot handle event "${event.type}" while in state "${state}"`);
    this.name = "InvalidTransitionError";
  }
}

const DEFAULT_CYCLE: readonly TrafficLightState[] = ["red", "green", "yellow"];

export class TrafficLight {
  private state: TrafficLightState = "red";
  private readonly cycle: readonly TrafficLightState[];
  private readonly allowButton: boolean;

  constructor(config: TrafficLightConfig = {}) {
    this.cycle = config.cycle ?? DEFAULT_CYCLE;
    this.allowButton = config.allowButton ?? false;
  }

  get current(): TrafficLightState {
    return this.state;
  }

  /** Returns the state that follows `state` in the configured cycle. */
  nextState(state: TrafficLightState = this.state): TrafficLightState {
    const index = this.cycle.indexOf(state);
    if (index === -1) {
      throw new InvalidTransitionError(state, { type: "timer" });
    }
    return this.cycle[(index + 1) % this.cycle.length];
  }

  /** Applies an event and returns the new state. */
  send(event: TrafficLightEvent): TrafficLightState {
    switch (event.type) {
      case "timer":
        this.state = this.nextState();
        return this.state;
      case "button":
        if (!this.allowButton) {
          throw new InvalidTransitionError(this.state, event);
        }
        this.state = this.nextState();
        return this.state;
      default: {
        // Exhaustiveness check: adding a new event type without handling it
        // becomes a compile-time error.
        const _exhaustive: never = event;
        return _exhaustive;
      }
    }
  }
}
```

## Usage

```ts
