export type Phase = 'red' | 'amber' | 'green';

/** Immutable snapshot of the machine. */
export interface TrafficLightState {
  readonly phase: Phase;
  /** Milliseconds left in the current phase. */
  readonly remainingMs: number;
  /** Whether a pedestrian is waiting to cross. */
  readonly pedestrianWaiting: boolean;
}

/** How long each phase lasts (ms). */
export const PHASE_DURATION_MS = {
  red: 10_000,
  amber: 3_000,
  green: 15_000,
} as const satisfies Readonly<Record<Phase, number>>;

export const initialState = (): TrafficLightState => ({
  phase: 'red',
  remainingMs: PHASE_DURATION_MS.red,
  pedestrianWaiting: false,
