## 2. Transition table + `next`

The table is the single source of truth; `satisfies` guarantees every phase has an entry *and* that the values are valid phases.

```ts
const NEXT_PHASE = {
  red: 'green',
  green: 'amber',
  amber: 'red',
} as const satisfies Readonly<Record<Phase, Phase>>;

/** Pure phase-to-phase transition. */
export function nextPhase(phase: Phase): Phase {
  return NEXT_PHASE[phase];
}

/**
 * Advance the machine by `elapsedMs`, rolling over into the next phase
 * (possibly several) if time runs out.
 */
export function next(
  state: TrafficLightState,
  elapsedMs = 1_000,
): TrafficLightState {
  let current = state;
  let remaining = elapsedMs;

  // Each iteration consumes one full phase.
  while (remaining >= current.remainingMs && current.remainingMs > 0) {
    remaining -= current.remainingMs;
    const phase = nextPhase(current.phase);
    current = { ...current, phase, remainingMs: PHASE_DURATION_MS[phase] };
  }

  return { ...current, remainingMs: current.remainingMs - remaining };
}
```

## 3. Event-driven reducer

```ts
export type TrafficEvent =
  | { readonly type: 'TICK'; readonly elapsedMs: number }
  | { readonly type: 'PEDESTRIAN_REQUEST' }
  | { readonly type: 'PEDESTRIAN_CLEARED' }
  | { readonly type: 'RESET' };

/** Compile-time exhaustiveness check. */
export function assertNever(value: never): never {
  throw new Error(`Unhandled variant: ${JSON.stringify(value)}`);
}

export function transition(
  state: TrafficLightState,
  event: TrafficEvent,
): TrafficLightState {
  switch (event.type) {
    case 'TICK':
      return next(state, event.elapsedMs);

    case 'PEDESTRIAN_REQUEST':
      return state.pedestrianWaiting
        ? state
        : { ...state, pedestrianWaiting: true };

    case 'PEDESTRIAN_CLEARED':
      return state.pedestrianWaiting
        ? { ...state, pedestrianWaiting: false }
        : state;

    case 'RESET':
      return initialState();

    default:
      return assertNever(event);
  }
}
```

## 4. Convenience wrapper

```ts
export class TrafficLight {
  #state: TrafficLightState = initialState();

  get state(): TrafficLightState {
    return this.#state;
  }

  dispatch(event: TrafficEvent): void {
    this.#state = transition(this.#state, event);
  }

  /** Convenience: the next state in the cycle. */
  get nextState(): TrafficLightState {
    return next(this.#state);
  }
}
```

## 5. Usage

```ts
const light = new TrafficLight();

light.dispatch({ type: 'TICK', elapsedMs: 10_000 }); // red -> green
console.log(light.state.phase);                      // 'green'

light.dispatch({ type: 'PEDESTRIAN_REQUEST' });
light.dispatch({ type: 'TICK', elapsedMs: 15_000 }); // green -> amber
console.log(light.state.phase);                      // 'amber'
```

## Notes on the typing choices

- **`as const satisfies Record<Phase, Phase>`** — `as const` preserves literal types (so `NEXT_PHASE.red` is `"green"`, not `string`), while `satisfies` validates the shape *without* widening. You get both autocomplete and safety.
- **Discriminated unions** on `event.type` let TypeScript narrow correctly in `switch`, and `assertNever` turns a missing case into a compile error rather than a runtime surprise.
- **`readonly` + spread** keeps state immutable, so `next`/`transition` are referentially transparent and easy to test or memoize.
- If you want a *typed* transition map keyed by state *and* event (e.g. `Record<Phase, Record<EventKind, Phase>>`), the same `satisfies` pattern scales: the compiler will flag any missing or extra edge.

```ts
// ---------- Types ----------

export type LightColor = "red" | "yellow" | "green";

/** A discriminated union: each state carries its own color-specific data. */
export type TrafficLightState =
  | { readonly color: "red"; readonly remainingMs: number }
  | { readonly color: "yellow"; readonly remainingMs: number }
  | { readonly color: "green"; readonly remainingMs: number };

export type TrafficLightEvent =
  | { readonly type: "timerExpired" }
  | { readonly type: "pedestrianRequested" };

/** Compile-time exhaustiveness helper. */
export type Never = never;

// ---------- Configuration ----------

export const DEFAULT_DURATIONS: Record<LightColor, number> = {
  red: 10_000,
  yellow: 3_000,
  green: 15_000,
};

// ---------- Transition function ----------

export function nextState(
  state: TrafficLightState,
  event: TrafficLightEvent,
  durations: Record<LightColor, number> = DEFAULT_DURATIONS,
): TrafficLightState {
  switch (state.color) {
    case "red":
      // Red always advances to green.
      return { color: "green", remainingMs: durations.green };

    case "green":
      // Green goes to yellow, or jumps straight to red if a pedestrian is waiting.
      return event.type === "pedestrianRequested"
        ? { color: "red", remainingMs: durations.red }
        : { color: "yellow", remainingMs: durations.yellow };

    case "yellow":
      // Yellow always advances to red.
      return { color: "red", remainingMs: durations.red };

    default: {
      // Fails to compile if a new color is added without handling it.
      const _exhaustive: Never = state;
      return _exhaustive;
    }
  }
}

// ---------- Helpers ----------

export function createInitialState(
  durations: Record<LightColor, number> = DEFAULT_DURATIONS,
): TrafficLightState {
  return { color: "red", remainingMs: durations.red };
}

export function tick(state: TrafficLightState, elapsedMs: number): TrafficLightState {
  const remainingMs = state.remainingMs - elapsedMs;
  return remainingMs <= 0
    ? nextState(state, { type: "timerExpired" })
    : { ...state, remainingMs };
}
```

**Example usage:**

```ts
let state = createInitialState();
// { color: "red", remainingMs: 10000 }

state = nextState(state, { type: "timerExpired" });
// { color: "green", remainingMs: 15000 }

state = nextState(state, { type: "pedestrianRequested" });
// { color: "red", remainingMs: 10000 }
```

Key points:
- `TrafficLightState` is a discriminated union on `color`, so TypeScript narrows it in `switch` statements.
- The `Never` check in the `default` branch makes the compiler error if a new color is added without a corresponding transition.
- `tick` demonstrates a time-driven transition while `nextState` handles the event-driven one.

## Types

```ts
// ---------- Primitives ----------

export const DIRECTIONS = ['north', 'south', 'east', 'west'] as const;
export type Direction = (typeof DIRECTIONS)[number];

export const COLORS = ['red', 'amber', 'green'] as const;
export type Color = (typeof COLORS)[number];

/**
 * The four phases a signal can be in.
 * `pedestrian-crossing` means: vehicles see red, pedestrians see walk.
 */
export type Phase = 'red' | 'green' | 'amber' | 'pedestrian-crossing';

export interface TrafficState {
  readonly direction: Direction;
  readonly phase: Phase;
}

export interface TransitionContext {
  /** A pedestrian is waiting to cross the current direction. */
  readonly pedestrianRequested?: boolean;
}
```

## Helpers

```ts
export function assertNever(value: never): never {
  throw new Error(`Unexpected value: ${JSON.stringify(value)}`);
}

/** The light colour actually shown to vehicles for a given phase. */
export function colorOf(state: TrafficState): Color {
  switch (state.phase) {
    case 'red':
    case 'pedestrian-crossing':
      return 'red';
    case 'green':
      return 'green';
    case 'amber':
      return 'amber';
    default:
      return assertNever(state.phase); // compile error if a phase is added
  }
}

/** The signal shown to pedestrians for a given phase. */
export function pedestrianSignalOf(state: TrafficState): 'stop' | 'walk' {
  return state.phase === 'pedestrian-crossing' ? 'walk' : 'stop';
}

export function nextDirection(direction: Direction): Direction {
  const i = DIRECTIONS.indexOf(direction);
  return DIRECTIONS[(i + 1) % DIRECTIONS.length];
}

/** Suggested phase durations (ms). */
export const PHASE_DURATION: Record<Phase, number> = {
  red: 5_000,
  green: 20_000,
  amber: 3_000,
  'pedestrian-crossing': 10_000,
};
```

## The transition function

```ts
export function nextState(
  state: TrafficState,
  context: TransitionContext = {},
): TrafficState {
  switch (state.phase) {
    case 'red':
      return { direction: state.direction, phase: 'green' };

    case 'green':
      return { direction: state.direction, phase: 'amber' };

    case 'amber':
      // Vehicles have cleared. If someone is waiting, give them a crossing
      // phase before rotating to the next direction.
      return context.pedestrianRequested
        ? { direction: state.direction, phase: 'pedestrian-crossing' }
        : { direction: nextDirection(state.direction), phase: 'red' };

    case 'pedestrian-crossing':
      return { direction: nextDirection(state.direction), phase: 'red' };

    default:
      return assertNever(state.phase);
  }
}
```

## Optional: a small state machine wrapper

```ts
export type Event =
  | { type: 'TICK' }
  | { type: 'PEDESTRIAN_REQUEST' };

export class TrafficLight {
  #state: TrafficState;
  #pedestrianRequested = false;

  constructor(initial: TrafficState = { direction: 'north', phase: 'red' }) {
    this.#state = initial;
  }

  get state(): TrafficState {
    return this.#state;
  }

  dispatch(event: Event): TrafficState {
    switch (event.type) {
      case 'TICK':
        this.#state = nextState(this.#state, {
          pedestrianRequested: this.#pedestrianRequested,
        });
        // A request is consumed once the crossing phase has been served.
        if (this.#state.phase !== 'pedestrian-crossing') {
          this.#pedestrianRequested = false;
        }
        break;
      case 'PEDESTRIAN_REQUEST':
        this.#pedestrianRequested = true;
        break;
      default:
        return assertNever(event);
    }
    return this.#state;
  }
}
```

## Usage

```ts
const light = new TrafficLight();

light.dispatch({ type: 'PEDESTRIAN_REQUEST' });

for (let i = 0; i < 4; i++) {
  const s = light.dispatch({ type: 'TICK' });
  console.log(s.direction, s.phase, colorOf(s), pedestrianSignalOf(s));
}
// north red red stop
// north green green stop
// north amber amber stop
// north pedestrian-crossing red walk
```

**Why this is type-safe**

- `Phase` is a closed union, so `switch` narrowing plus `assertNever` in the `default` branch makes the compiler error if you add a phase and forget a transition.
- `TrafficState` is `readonly`, so transitions must produce a new object rather than mutating in place.
- `DIRECTIONS`/`COLORS` are `as const` tuples, so the derived types stay in sync with the runtime values and `nextDirection` is guaranteed to return a valid member.

## Basic state machine

```ts
// The set of valid states, as a string literal union
export type TrafficLightState = "red" | "yellow" | "green";

// Transition table. Using `Record` guarantees every state has an entry,
// and the value type guarantees only valid states are produced.
const TRANSITIONS: Record<TrafficLightState, TrafficLightState> = {
  red: "green",
  green: "yellow",
  yellow: "red",
};

export function getNextState(state: TrafficLightState): TrafficLightState {
  return TRANSITIONS[state];
}
```

Usage:

```ts
getNextState("red");    // "green"
getNextState("green");  // "yellow"
getNextState("yellow"); // "red"

// @ts-expect-error — invalid state
getNextState("blue");
```

## Exhaustive-checked version

If you want the compiler to catch a missing transition when you add a new state:

```ts
export type TrafficLightState = "red" | "yellow" | "green";

const TRANSITIONS = {
  red: "green",
  green: "yellow",
  yellow: "red",
} satisfies Record<TrafficLightState, TrafficLightState>;

export type TransitionKey = keyof typeof TRANSITIONS;

// Compile-time error if a state is added but no transition is defined
type AssertAllStatesCovered = Exclude<TrafficLightState, TransitionKey> extends never
  ? true
  : never;

export function getNextState(state: TrafficLightState): TrafficLightState {
  return TRANSITIONS[state];
}
```

## Richer variant: states as objects

```ts
export type TrafficLightState =
  | { kind: "red"; durationMs: number }
  | { kind: "yellow"; durationMs: number }
  | { kind: "green"; durationMs: number };

export type TrafficLightKind = TrafficLightState["kind"];

const NEXT_KIND: Record<TrafficLightKind, TrafficLightKind> = {
  red: "green",
  green: "yellow",
  yellow: "red",
};

export function getNextState(state: TrafficLightState): TrafficLightState {
  const kind = NEXT_KIND[state.kind];
  const durationMs = kind === "green" ? 30_000 : kind === "yellow" ? 3_000 : 30_000;
  return { kind, durationMs };
}
```

## Optional: a small state machine class

```ts
export class TrafficLight {
  #state: TrafficLightState = "red";

  get state(): TrafficLightState {
    return this.#state;
  }

  tick(): TrafficLightState {
    this.#state = getNextState(this.#state);
    return this.#state;
  }
