```

The key idea: model states as a literal union and transitions as a `Record` keyed by that union. TypeScript then rejects invalid states, invalid targets, and (with `satisfies`) missing transitions at compile time.

```ts
// ---------- Types ----------

export type Light = "red" | "yellow" | "green";

export interface TrafficLightState {
  readonly light: Light;
  /** Time spent in the current phase, in milliseconds. */
  readonly elapsedMs: number;
}

/** How long each phase lasts. */
export const PHASE_DURATION_MS: Readonly<Record<Light, number>> = {
  red: 10_000,
  yellow: 3_000,
  green: 15_000,
};

/** The order the phases cycle in. */
const NEXT_LIGHT: Readonly<Record<Light, Light>> = {
  red: "green",
  green: "yellow",
  yellow: "red",
};

/** Compile-time exhaustiveness check. */
function assertNever(value: never): never {
  throw new Error(`Unhandled state: ${JSON.stringify(value)}`);
}

// ---------- Transition function ----------

/**
 * Advances the machine by `deltaMs` and returns the resulting state.
 * A phase rolls over to the next one as soon as its duration is reached;
 * leftover time is carried over into the new phase.
 */
export function nextState(
  state: TrafficLightState,
  deltaMs: number,
): TrafficLightState {
  if (deltaMs < 0) {
    throw new RangeError("deltaMs must be non-negative");
  }

  const duration = PHASE_DURATION_MS[state.light];
  const total = state.elapsedMs + deltaMs;

  if (total < duration) {
    return { light: state.light, elapsedMs: total };
  }

  const next = NEXT_LIGHT[state.light];
  return { light: next, elapsedMs: total - duration };
}

/** Convenience: the light that follows the given one. */
export function nextLight(light: Light): Light {
  switch (light) {
    case "red":
      return "green";
    case "green":
      return "yellow";
    case "yellow":
      return "red";
    default:
      return assertNever(light);
  }
}
```

Example:

```ts
let state: TrafficLightState = { light: "red", elapsedMs: 0 };

state = nextState(state, 4_000);   // { light: "red",    elapsedMs: 4000 }
state = nextState(state, 7_000);   // { light: "green",  elapsedMs: 1000 }
state = nextState(state, 15_000);  // { light: "yellow", elapsedMs: 1000 }
```

Notes:
- `Light` is a closed string union, so typos are compile errors.
- `NEXT_LIGHT` is typed as `Record<Light, Light>`, meaning adding a new light forces you to supply its transition.
- `assertNever` (via the `default` branch) guarantees the switch in `nextLight` stays exhaustive.
- States are `readonly`, so a transition can't mutate the current state — it returns a new one.

## 1. Simple single-light state machine

```ts
export type Phase = 'red' | 'green' | 'yellow';
export type SignalState = Phase;

/**
 * The transition table is the single source of truth.
 * `satisfies` checks the shape *and* keeps the literal types narrow.
 */
export const TRANSITIONS = {
  red: 'green',
  green: 'yellow',
  yellow: 'red',
} satisfies { readonly [S in SignalState]: SignalState };

export function nextState(current: SignalState): SignalState {
  return TRANSITIONS[current];
}
```

## 2. Intersection (direction-aware) version

Template-literal types let you model `"which axis + which color"` as one type:

```ts
export type Direction = 'NS' | 'EW';
export type Phase = 'red' | 'green' | 'yellow';

/** e.g. "NS:green" | "EW:red" | ... */
export type SignalState = `${Direction}:${Phase}`;

export const TRANSITIONS = {
  'NS:green': 'NS:yellow',
  'NS:yellow': 'NS:red',
  'NS:red': 'EW:green',
  'EW:green': 'EW:yellow',
  'EW:yellow': 'EW:red',
  'EW:red': 'NS:green',
} satisfies { readonly [S in SignalState]: SignalState };

export function nextState(current: SignalState): SignalState {
  return TRANSITIONS[current];
}
```

### Exhaustive matching with a discriminated union

If you'd rather work with objects (easier to attach metadata like timers), use a discriminated union and let the compiler prove your `switch` covers every case:

```ts
export interface Signal<S extends SignalState = SignalState> {
  readonly state: S;
}

export type MachineState =
  | { readonly kind: 'signal'; readonly direction: Direction; readonly phase: Phase }
  | { readonly kind: 'pedestrian'; readonly crossing: boolean };

export function describe(state: MachineState): string {
  switch (state.kind) {
    case 'signal':
      return `${state.direction} is ${state.phase}`;
    case 'pedestrian':
      return state.crossing ? 'Walk' : "Don't walk";
    default: {
      // Compile error if a new variant is added without handling it
      const _exhaustive: never = state;
      return _exhaustive;
    }
  }
}
```

## 3. Runtime-safe wrapper

States often come from JSON, sockets, or user input — validate before trusting them:

```ts
const VALID_STATES = Object.keys(TRANSITIONS) as SignalState[];

export function isSignalState(value: unknown): value is SignalState {
  return typeof value === 'string' && (VALID_STATES as string[]).includes(value);
}

export function nextStateSafe(current: unknown): SignalState | undefined {
  return isSignalState(current) ? TRANSITIONS[current] : undefined;
}
```

## 4. Optional: a small state machine class

```ts
export class TrafficLight {
  #state: SignalState;

  constructor(initial: SignalState = 'NS:red') {
    if (!isSignalState(initial)) throw new Error(`Invalid state: ${initial}`);
    this.#state = initial;
  }

  get state(): SignalState {
    return this.#state;
  }

  /** Advance one phase and return the new state. */
  tick(): SignalState {
    this.#state = TRANSITIONS[this.#state];
    return this.#state;
  }

  /** The phase shown for a given axis. */
  phaseFor(direction: Direction): Phase {
    const [dir, phase] = this.#state.split(':') as [Direction, Phase];
    return dir === direction ? phase : 'red';
  }
}
```

**Why the transition table instead of a `switch`?** The table is data, so it can be validated, serialized, tested exhaustively, and reused at runtime (e.g. to build a cycle graph). The `satisfies` clause gives you compile-time guarantees that every state has exactly one successor, and the mapped type `{ [S in SignalState]: SignalState }` guarantees *all* states are covered — adding a new state without adding its transition is a type error.

```ts
// The three possible states of a traffic light.
export type TrafficLightState = "red" | "yellow" | "green";

// Events that can trigger a transition.
export type TrafficLightEvent = "timer" | "button";

// A transition table: (state, event) -> next state.
// Using a Record keeps the compiler in sync with the state union,
// so adding a new state forces you to handle it here.
export type TransitionTable = {
  [S in TrafficLightState]: {
    [E in TrafficLightEvent]?: TrafficLightState;
  };
};

export const transitions: TransitionTable = {
  red: {
    timer: "green",
    button: "green",
  },
  green: {
    timer: "yellow",
    button: "yellow",
  },
  yellow: {
    timer: "red",
    button: "red",
  },
};

/**
 * Returns the next state for the given state and event.
 * Falls back to the current state if no transition is defined.
 */
export function getNextState(
  state: TrafficLightState,
  event: TrafficLightEvent = "timer",
): TrafficLightState {
  return transitions[state][event] ?? state;
}

// --- Simple cycle variant -------------------------------------------------

const cycle: Record<TrafficLightState, TrafficLightState> = {
  red: "green",
  green: "yellow",
  yellow: "red",
};

/** Returns the next state in the fixed red -> green -> yellow -> red cycle. */
export function nextState(state: TrafficLightState): TrafficLightState {
  return cycle[state];
}
```

Example usage:

```ts
nextState("red");                    // "green"
nextState("green");                  // "yellow"
nextState("yellow");                 // "red"

getNextState("green", "button");     // "yellow"
getNextState("red", "timer");        // "green"
```

The `Record`/`TransitionTable` approach means that if you add `"orange"` to `TrafficLightState`, TypeScript will error until every transition for it is defined — making the type system enforce exhaustiveness at compile time.

## Core design

Model the machine as a **transition table**: a total map from `(state, event) → state`. This keeps the rules declarative and makes illegal transitions impossible to express by accident.

```ts
// ---------- Types ----------

export type Phase = "red" | "yellow" | "green";

export type EventType =
  | "timer"          // phase duration elapsed
  | "pedestrianCall" // walk button pressed
  | "vehicleDetected"
  | "emergency";     // e.g. ambulance approaching

export type TransitionTable = {
  readonly [P in Phase]: { readonly [E in EventType]?: Phase };
};

export type Transition = {
  readonly from: Phase;
  readonly event: EventType;
  readonly to: Phase;
};

// ---------- Transition table ----------

export const TRANSITIONS: TransitionTable = {
  red: {
    timer: "green",
    pedestrianCall: "green",
    vehicleDetected: "green",
    emergency: "red",
  },
  yellow: {
    timer: "red",
    emergency: "red",
  },
  green: {
    timer: "yellow",
    emergency: "red",
  },
};

// ---------- Core function ----------

/** Returns the next phase, or `undefined` if the event is not valid in `phase`. */
export function nextPhase(phase: Phase, event: EventType): Phase | undefined {
  return TRANSITIONS[phase][event];
}

/** Strict variant: throws on an invalid (state, event) pair. */
export function next(phase: Phase, event: EventType): Phase {
  const to = nextPhase(phase, event);
  if (to === undefined) {
    throw new Error(`Invalid transition: ${phase} --${event}-->`);
  }
  return to;
}

export function canTransition(phase: Phase, event: EventType): boolean {
  return nextPhase(phase, event) !== undefined;
}

/** All events that are meaningful in a given phase. */
export function allowedEvents(phase: Phase): EventType[] {
  return Object.keys(TRANSITIONS[phase]) as EventType[];
}
```

## Adding context (time-in-phase, pedestrian waiting)

Real lights don't switch the instant the timer fires — they respect a minimum duration. Promote the machine to a reducer over `(state, event)` where state carries context:

```ts
export interface LightState {
  readonly phase: Phase;
  readonly ticksInPhase: number;
  readonly pedestrianWaiting: boolean;
}

export type LightEvent =
  | { readonly type: "timer" }
  | { readonly type: "pedestrianCall" }
  | { readonly type: "vehicleDetected" }
  | { readonly type: "emergency" };

export const MIN_TICKS: Record<Phase, number> = {
  red: 3,
  green: 5,
  yellow: 2,
};

export function initialState(): LightState {
  return { phase: "red", ticksInPhase: 0, pedestrianWaiting: false };
}

export function reduce(state: LightState, event: LightEvent): LightState {
  switch (event.type) {
    case "pedestrianCall":
      return { ...state, pedestrianWaiting: true };

    case "vehicleDetected":
      // Only meaningful while red.
      return state.phase === "red" ? state : state;

    case "emergency":
      return { ...state, phase: "red", ticksInPhase: 0 };

    case "timer": {
      const ticks = state.ticksInPhase + 1;
      if (ticks < MIN_TICKS[state.phase]) {
        return { ...state, ticksInPhase: ticks };
      }
      const to = nextPhase(state.phase, "timer");
      if (to === undefined) return state; // unreachable, but type-safe
      return {
        phase: to,
        ticksInPhase: 0,
        pedestrianWaiting: state.pedestrianWaiting && to !== "green",
      };
    }

    default: {
      // Compile-time exhaustiveness check: adding a new event type
      // makes this line a type error until handled.
      const _exhaustive: never = event;
      return _exhaustive;
    }
  }
}
```

## Exhaustiveness helpers

```ts
export function assertNever(value: never): never {
  throw new Error(`Unhandled variant: ${JSON.stringify(value)}`);
}

/** Compile-time proof that every phase has a transition table entry. */
type _AllPhasesCovered = keyof TransitionTable extends Phase ? true : never;
const _check: _AllPhasesCovered = true;
```

## Notes

- **Discriminated unions** (`{ type: "timer" } | { type: "emergency" }`) let TypeScript narrow on `event.type` and enable the `never` exhaustiveness check.
- **`Partial<Record<EventType, Phase>>`** in the table type means "some events are illegal in some phases" — `undefined` is the honest representation of that, so `nextPhase` returns `Phase | undefined` while `next` throws.
- If you want the table to be *fully* total (every event valid in every phase), drop the `?` and `nextPhase` becomes non-optional — but then invalid transitions can only be modelled as self-loops.
- For a larger system, the same table drives: unit tests (`expect(next("red", "timer")).toBe("green")`), documentation generation, and simulation/fuzzing of event sequences.

## Core: states, transitions, and `nextState`

```ts
// ---------------------------------------------------------------------------
// States
// ---------------------------------------------------------------------------

export const TRAFFIC_LIGHT_STATES = ['red', 'yellow', 'green'] as const;

/** The three possible states of the light. */
export type TrafficLightState = (typeof TRAFFIC_LIGHT_STATES)[number];

// ---------------------------------------------------------------------------
// Transitions
// ---------------------------------------------------------------------------

/**
 * The transition table. Typing it as a mapped type over `TrafficLightState`
 * means adding a new state is a compile-time error until every state has a
 * successor defined.
 */
export const TRANSITIONS: Readonly<Record<TrafficLightState, TrafficLightState>> = {
  red: 'green',
  green: 'yellow',
  yellow: 'red',
};

// ---------------------------------------------------------------------------
// The function
// ---------------------------------------------------------------------------

/** Returns the state the light moves to after `state`. */
export function nextState(state: TrafficLightState): TrafficLightState {
  return TRANSITIONS[state];
}
```

## Runtime guards & helpers

```ts
/** Type guard for values coming from untyped input (JSON, DOM, network…). */
export function isTrafficLightState(value: unknown): value is TrafficLightState {
  return typeof value === 'string' && (TRAFFIC_LIGHT_STATES as readonly string[]).includes(value);
}

/** Compile-time exhaustiveness check. */
function assertNever(value: never): never {
  throw new Error(`Unhandled variant: ${JSON.stringify(value)}`);
}

/** Number of seconds each state is displayed. */
export const DURATIONS: Readonly<Record<TrafficLightState, number>> = {
  red: 30,
  yellow: 3,
  green: 25,
};
```

## A small stateful machine

```ts
export class TrafficLight {
  #state: TrafficLightState = 'red';

  get state(): TrafficLightState {
    return this.#state;
  }

  /** Advances the light and returns the new state. */
  tick(): TrafficLightState {
    this.#state = nextState(this.#state);
    return this.#state;
  }

  /** Advances the light `n` times. */
  tickMany(n: number): TrafficLightState[] {
    const states: TrafficLightState[] = [];
    for (let i = 0; i < n; i++) {
      states.push(this.tick());
    }
    return states;
  }
}
```

## Event-driven variant (optional)

If the light reacts to events rather than a timer, model the events as a
discriminated union and key the transition table by `(state, event)`:

```ts
export type TrafficLightEvent =
  | { type: 'timer-expired' }
  | { type: 'pedestrian-requested' };

type TransitionTable = {
  readonly [S in TrafficLightState]: {
    readonly [E in TrafficLightEvent['type']]: TrafficLightState;
  };
};

export const EVENT_TRANSITIONS: TransitionTable = {
  red: {
    'timer-expired': 'green',
    'pedestrian-requested': 'red',
  },
  green: {
    'timer-expired': 'yellow',
    'pedestrian-requested': 'yellow',
  },
  yellow: {
    'timer-expired': 'red',
    'pedestrian-requested': 'red',
  },
};

export function nextStateFor(
  state: TrafficLightState,
  event: TrafficLightEvent,
): TrafficLightState {
  return EVENT_TRANSITIONS[state][event.type];
}
```

## Why this is type-safe

| Technique | What it buys you |
|---|---|
| `as const` + indexed access | `TrafficLightState` is a *narrow* union — not `string` — so typos are rejected. |
| `Record<TrafficLightState, …>` | Adding/removing a state forces you to update the transition table; the compiler points at every missing entry. |
| `isTrafficLightState` | Safely narrows `unknown` (e.g. parsed JSON) to the union before use. |
| Discriminated union of events | `event.type` is checked exhaustively; `switch` statements on it get a `never` default for free. |
| `assertNever` | Any new event/state variant that isn't handled becomes a compile-time error rather than a silent runtime bug. |

A quick sanity check:

```ts
const light = new TrafficLight();
light.tickMany(4); // ['green', 'yellow', 'red', 'green']

nextState('green');   // 'yellow'
nextState('purple');  // ❌ compile error: not assignable to 'TrafficLightState'
```

```ts
// The possible states of a single traffic light
export type LightState = "red" | "yellow" | "green";

// The transition table: each state maps to its next state
const TRANSITIONS: Record<LightState, LightState> = {
  red: "green",
  green: "yellow",
  yellow: "red",
};

/**
 * Returns the next state of the traffic light.
 * Throws at runtime if given an invalid state (compile-time safety via `never`).
 */
export function nextState(current: LightState): LightState {
  const next = TRANSITIONS[current];
  if (next === undefined) {
    throw new Error(`Invalid traffic light state: ${String(current)}`);
  }
  return next;
}
```

### With exhaustiveness checking

If you add a new state, TypeScript will flag every place that needs updating:

```ts
export type LightState = "red" | "yellow" | "green";

function assertNever(value: never): never {
  throw new Error(`Unhandled state: ${String(value)}`);
}

export function nextState(current: LightState): LightState {
  switch (current) {
    case "red":
      return "green";
    case "green":
      return "yellow";
    case "yellow":
      return "red";
    default:
      return assertNever(current); // Error if a new state is added without handling
  }
}
```

### As a typed state machine object

```ts
export interface TrafficLight {
  readonly state: LightState;
  tick(): TrafficLight; // returns a new machine in the next state
}

export function createTrafficLight(initial: LightState = "red"): TrafficLight {
  return {
    state: initial,
    tick(): TrafficLight {
      return createTrafficLight(nextState(this.state));
    },
  };
}

// Usage
const light = createTrafficLight("green");
console.log(light.tick().state); // "yellow"
```

Key points:
- **`Record<LightState, LightState>`** guarantees every state has a transition defined at compile time.
- **`never` + `assertNever`** makes the switch exhaustive, so adding a state produces a compile error until all transitions are handled.
- Immutability (`readonly state`, returning a new machine) keeps state changes predictable.
